#!/usr/bin/env python3
import ast,operator,sys
OPS={ast.Add:operator.add,ast.Sub:operator.sub,ast.Mult:operator.mul,ast.Div:operator.truediv,ast.UAdd:operator.pos,ast.USub:operator.neg}
def f(n):
    if isinstance(n,ast.Expression): return f(n.body)
    if isinstance(n,ast.Constant) and isinstance(n.value,(int,float)): return n.value
    if isinstance(n,ast.BinOp) and type(n.op) in OPS: return OPS[type(n.op)](f(n.left),f(n.right))
    if isinstance(n,ast.UnaryOp) and type(n.op) in OPS: return OPS[type(n.op)](f(n.operand))
    raise ValueError
x=" ".join(sys.argv[1:])
try:
    r=f(ast.parse(x,mode="eval"))
    print(int(r) if isinstance(r,float) and r.is_integer() else r)
except Exception:
    sys.exit(1)
